#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, T;
    cin >> N >> T;

    vector<int> type(N);
    for (int i = 0; i < N; ++i) cin >> type[i];

    vector<vector<int>> prices(T + 1);
    for (int i = 0; i < N; ++i) {
        int p;
        cin >> p;
        prices[type[i]].push_back(p);
    }

    vector<int> idx(T + 1, 0);
    set<pair<int, int>> global;

    for (int t = 1; t <= T; ++t) {
        if (!prices[t].empty()) {
            sort(prices[t].begin(), prices[t].end());
            global.insert({prices[t][0], t});
        }
    }

    int C;
    cin >> C;

    long long answer = 0;

    for (int i = 0; i < C; ++i) {
        int u;
        cin >> u;

        if (u == 0) {
            if (global.empty()) continue;

            auto it = global.begin();
            int p = it->first;
            int t = it->second;

            answer += p;
            global.erase(it);

            ++idx[t];
            if (idx[t] < (int)prices[t].size()) {
                global.insert({prices[t][idx[t]], t});
            }
        } else {
            int t = u;
            if (idx[t] >= (int)prices[t].size()) continue;

            int p = prices[t][idx[t]];
            answer += p;

            global.erase({p, t});
            ++idx[t];

            if (idx[t] < (int)prices[t].size()) {
                global.insert({prices[t][idx[t]], t});
            }
        }
    }

    cout << answer << '\n';
    return 0;
}
